INSERT INTO modules (id, domain_id, title, description, owner_id, status, version, overall_threshold, estimated_minutes) VALUES
  ('m0000000-0001-4000-8000-000000000001', 'd0000000-0001-4000-8000-000000000001', 'Digital Multimeter Fundamentals and Safety', 'Prepare for hands-on multimeter use by understanding measurement principles, correct connection procedures, safety requirements, and common error sources.', 'a1b2c3d4-1001-4000-8000-000000000001', 'published', '1.2.0', 0.8, 25)
INSERT INTO competencies (id, module_id, name, description, weight, min_threshold, mandatory, critical, sequence) VALUES
  ('c0000000-0001-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Measurement Theory', 'Understanding of voltage, current, and resistance measurement principles', 0.25, 0.6, true, false, 1),
  ('c0000000-0002-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Connection Procedures', 'Correct probe placement and mode selection for each measurement type', 0.30, 0.7, true, false, 2),
  ('c0000000-0003-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Safety Compliance', 'Critical safety rules, PPE, and prohibited actions', 0.30, 0.8, true, true, 3),
  ('c0000000-0004-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Error Awareness', 'Common measurement errors and their prevention', 0.15, 0.5, false, false, 4)
INSERT INTO activities (id, module_id, title, activity_type, sequence, content, explanation, warning, competency_id) VALUES
  ('ac000000-0001-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Understanding Your Digital Multimeter', 'instruction', 1, 'A digital multimeter (DMM) measures voltage, current, and resistance. The display shows the measured value, while the rotary selector chooses the measurement function and range. Most modern DMMs have auto-ranging capability.', 'The DMM is the most common instrument in electronics laboratories. Understanding its functions before use prevents measurement errors and equipment damage.', NULL, 'c0000000-0001-4000-8000-000000000001'),
  ('ac000000-0002-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Voltage Measurement — Parallel Connection', 'demonstration', 2, 'Voltage is always measured in PARALLEL with the component. Connect the red probe to the V/Ω terminal and the black probe to COM. Place probes across the component while the circuit is energised. The multimeter presents very high input impedance so it draws negligible current.', 'Parallel connection means the multimeter measures the potential difference across the component without significantly altering circuit behaviour.', NULL, 'c0000000-0002-4000-8000-000000000001'),
  ('ac000000-0003-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Current Measurement — Series Connection', 'demonstration', 3, 'Current is measured in SERIES with the circuit. You must break the circuit and insert the multimeter so all current flows through it. Connect the red probe to the mA/A terminal (not the V/Ω terminal). Select the appropriate current range BEFORE connecting.', 'Series connection ensures all circuit current passes through the meter. Using the wrong terminal or connecting in parallel while in current mode can blow the internal fuse or damage the meter.', 'Never connect the multimeter in parallel when set to current measurement mode. This creates a short circuit.', 'c0000000-0002-4000-8000-000000000001'),
  ('ac000000-0004-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Critical Safety Rules', 'warning', 4, 'CRITICAL RULES: 1. Never exceed the maximum input voltage rating (typically 600V CAT III or 1000V CAT II). 2. Always verify the measurement mode BEFORE connecting probes to a live circuit. 3. Never measure resistance in a live (energised) circuit. 4. Use appropriate PPE (safety glasses, insulated gloves for >50V). 5. Inspect probe insulation before every use — do not use damaged probes.', 'These rules are non-negotiable. Violation can cause equipment damage, electric shock, arc flash, or fire. A failure to demonstrate understanding of any critical rule prevents a Ready status.', 'Failure to follow these rules can result in serious injury or death. These are mandatory requirements.', 'c0000000-0003-4000-8000-000000000001'),
  ('ac000000-0005-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Resistance Measurement Procedure', 'instruction', 5, 'To measure resistance: 1) De-energise the circuit completely. 2) Disconnect the component if possible. 3) Select resistance mode (Ω). 4) Connect probes across the component. 5) Read the value. The meter applies a small test voltage — if the circuit is live, the reading will be incorrect and the meter may be damaged.', 'Resistance measurement requires a de-energised circuit because the DMM injects its own test signal. External voltage interferes with this signal and can damage the meter.', 'Always ensure the circuit is completely de-energised before measuring resistance.', 'c0000000-0002-4000-8000-000000000001'),
  ('ac000000-0006-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Common Measurement Errors', 'practice', 6, 'Common errors to recognise: Probes in wrong terminals (V terminal when measuring current), Wrong mode selected (AC vs DC), Measuring resistance in a live circuit, Not zeroing the meter before low-resistance measurement, Loose probe connections giving unstable readings, Exceeding the range (reading shows "OL" or "1.")', 'Recognising these error patterns helps you troubleshoot unexpected readings before assuming the circuit has a fault.', NULL, 'c0000000-0004-4000-8000-000000000001'),
  ('ac000000-0007-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'Pre-Lab Checklist Review', 'reflection', 7, 'Before entering the laboratory, confirm you can answer: How do I connect probes for voltage vs current measurement? What mode and terminal do I use for each measurement? What must I check before measuring resistance? What are the critical safety rules I must never violate? How do I recognise a measurement error?', 'This checklist mirrors what your readiness assessment will evaluate. If you cannot answer these confidently, review the relevant steps above.', NULL, 'c0000000-0001-4000-8000-000000000001')
INSERT INTO questions (id, module_id, competency_id, question_text, question_type, options, correct_answer, explanation, critical, source_reference, question_kind, approval_status) VALUES
  ('q0000000-0001-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0001-4000-8000-000000000001', 'Why must voltage be measured in parallel with a component rather than in series?', 'multiple-choice', '["Because the multimeter needs high current to measure voltage","Because parallel connection allows the meter to measure potential difference without significantly altering circuit current","Because series connection would give a higher voltage reading","Because the multimeter cannot physically be connected in series"]'::jsonb, 'Because parallel connection allows the meter to measure potential difference without significantly altering circuit current', 'A voltmeter has very high input impedance and is connected in parallel to measure the potential difference across a component without drawing significant current from the circuit.', false, 'DMM Manual v3.1, Section 2.1 — Voltage Measurement Principles', 'assessment', 'approved'),
  ('q0000000-0002-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0002-4000-8000-000000000001', 'When measuring current, which terminal should the red probe be connected to?', 'multiple-choice', '["The V/Ω terminal","The COM terminal","The mA/A terminal","Any terminal — it does not matter for current measurement"]'::jsonb, 'The mA/A terminal', 'For current measurement, the red probe must be in the mA or A terminal (depending on expected range). Using the V/Ω terminal while in current mode creates a short circuit path.', false, 'DMM Manual v3.1, Section 3.2 — Current Measurement Connections', 'assessment', 'approved'),
  ('q0000000-0003-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0003-4000-8000-000000000001', 'What must you verify BEFORE connecting multimeter probes to a live circuit?', 'multiple-choice', '["That the battery is fully charged","That the measurement mode and range are correctly set for the intended measurement","That the display backlight is working","That the auto-range feature is enabled"]'::jsonb, 'That the measurement mode and range are correctly set for the intended measurement', 'Connecting probes with the wrong mode selected can create dangerous short circuits, blow fuses, or damage equipment. Always verify mode BEFORE connecting to a live circuit.', true, 'DMM Manual v3.1, Section 5.1 — Critical Safety Procedures', 'assessment', 'approved'),
  ('q0000000-0004-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0003-4000-8000-000000000001', 'Why is it dangerous to measure resistance in a live (energised) circuit?', 'multiple-choice', '["It gives slightly inaccurate readings","The display may flicker","The external voltage can damage the meter, give false readings, and create a safety hazard","It only matters for resistance values above 1MΩ"]'::jsonb, 'The external voltage can damage the meter, give false readings, and create a safety hazard', 'The DMM injects a small test voltage for resistance measurement. External circuit voltage overwhelms this signal, causing incorrect readings, potential meter damage, and possible shock or arc hazard.', true, 'DMM Manual v3.1, Section 5.3 — Resistance Measurement Safety', 'assessment', 'approved'),
  ('q0000000-0005-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0004-4000-8000-000000000001', 'You see "OL" on the multimeter display while measuring resistance. What does this most likely indicate?', 'multiple-choice', '["The battery is low","The circuit is open (infinite resistance) or the component value exceeds the selected range","The probes are connected correctly","The measurement is complete and should be recorded as zero"]'::jsonb, 'The circuit is open (infinite resistance) or the component value exceeds the selected range', '"OL" (overload) means the resistance is beyond the meter''s ability to measure in the current range. This typically means an open circuit, a disconnected component, or a need to select a higher range.', false, 'DMM Manual v3.1, Section 6.2 — Interpreting Display Indicators', 'assessment', 'approved')
INSERT INTO questions (id, module_id, competency_id, question_text, question_type, options, correct_answer, explanation, critical, question_kind, activity_id, approval_status, failure_hint, min_read_seconds, generated_at, approved_by, approved_at) VALUES
  ('cp000000-0001-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0001-4000-8000-000000000001', 'What does the rotary selector on a digital multimeter control?', 'multiple-choice', '["The brightness of the display","The measurement function and range","The battery level indicator","The probe connection type"]'::jsonb, 'The measurement function and range', 'The rotary selector chooses which measurement function and range the multimeter uses.', false, 'checkpoint', 'ac000000-0001-4000-8000-000000000001', 'approved', 'Re-read the first paragraph about the rotary selector and its purpose.', 20, '2026-07-25T09:00:00Z', 'a1b2c3d4-1001-4000-8000-000000000001', '2026-07-26T10:00:00Z'),
  ('cp000000-0002-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0002-4000-8000-000000000001', 'How must a voltmeter be connected to measure the potential difference across a component?', 'multiple-choice', '["In series with the component","In parallel with the component","Disconnected from the circuit","Connected to ground only"]'::jsonb, 'In parallel with the component', 'Voltage is always measured in parallel.', false, 'checkpoint', 'ac000000-0002-4000-8000-000000000001', 'approved', 'Review the key principle: voltage = parallel connection.', 25, '2026-07-25T09:00:00Z', 'a1b2c3d4-1001-4000-8000-000000000001', '2026-07-26T10:05:00Z'),
  ('cp000000-0003-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0002-4000-8000-000000000001', 'What must you do to the circuit before inserting the multimeter for current measurement?', 'multiple-choice', '["Increase the voltage","Break the circuit so current flows through the meter","Add a parallel resistor","Nothing — just touch the probes to any point"]'::jsonb, 'Break the circuit so current flows through the meter', 'Current measurement requires series insertion.', false, 'checkpoint', 'ac000000-0003-4000-8000-000000000001', 'approved', 'Focus on the word SERIES. The circuit must be broken.', 30, '2026-07-25T09:00:00Z', 'a1b2c3d4-1001-4000-8000-000000000001', '2026-07-26T10:10:00Z'),
  ('cp000000-0004-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0003-4000-8000-000000000001', 'What is the consequence of failing to verify the measurement mode BEFORE connecting probes to a live circuit?', 'multiple-choice', '["The display shows a slightly wrong number","The backlight turns off","It can create dangerous short circuits, blow fuses, or damage equipment","The auto-range takes longer to settle"]'::jsonb, 'It can create dangerous short circuits, blow fuses, or damage equipment', 'Wrong mode + live circuit = potential short circuit.', true, 'checkpoint', 'ac000000-0004-4000-8000-000000000001', 'approved', 'THIS IS A CRITICAL SAFETY RULE. Re-read all 5 critical rules carefully.', 45, '2026-07-25T09:00:00Z', 'a1b2c3d4-1001-4000-8000-000000000001', '2026-07-26T10:15:00Z'),
  ('cp000000-0005-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0002-4000-8000-000000000001', 'What is the FIRST step before measuring resistance?', 'multiple-choice', '["Select the highest range","Connect the red probe to the mA terminal","De-energise the circuit completely","Zero the display"]'::jsonb, 'De-energise the circuit completely', 'Resistance measurement requires a dead circuit.', false, 'checkpoint', 'ac000000-0005-4000-8000-000000000001', 'approved', 'Look at step 1 of the resistance procedure.', 25, '2026-07-25T09:00:00Z', 'a1b2c3d4-1001-4000-8000-000000000001', '2026-07-26T10:20:00Z'),
  ('cp000000-0006-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0004-4000-8000-000000000001', 'If you see "OL" on the display while measuring resistance, what should you suspect?', 'multiple-choice', '["The battery needs replacing","The circuit is open or the value exceeds the selected range","The measurement is complete and correct","The probes are correctly connected"]'::jsonb, 'The circuit is open or the value exceeds the selected range', '"OL" means overload.', false, 'checkpoint', 'ac000000-0006-4000-8000-000000000001', 'approved', 'Look at the error patterns list. Find "OL".', 30, '2026-07-25T09:00:00Z', 'a1b2c3d4-1001-4000-8000-000000000001', '2026-07-26T10:25:00Z'),
  ('cp000000-0007-4000-8000-000000000001', 'm0000000-0001-4000-8000-000000000001', 'c0000000-0001-4000-8000-000000000001', 'Before entering the laboratory, which of the following should you be able to answer confidently?', 'multiple-choice', '["The price of the multimeter model","How to connect probes for voltage vs current, safety rules, and how to recognise errors","The manufacturer warranty terms","How to calibrate the meter"]'::jsonb, 'How to connect probes for voltage vs current, safety rules, and how to recognise errors', 'The pre-lab checklist covers connections, modes, prerequisites, safety, and errors.', false, 'checkpoint', 'ac000000-0007-4000-8000-000000000001', 'approved', 'Review the 5 checklist questions.', 20, '2026-07-25T09:00:00Z', 'a1b2c3d4-1001-4000-8000-000000000001', '2026-07-26T10:30:00Z')
